function para_hamming_quant(output_dir)
%PARA_HAMMING_QUANT Generate apodization coefficient JSON and C source.
this_dir = fileparts(mfilename('fullpath'));
addpath(fullfile(this_dir, 'scripts'));
if nargin < 1 || isempty(output_dir)
    output_dir = fullfile(this_dir, '..', 'configs');
end

hamming_win = hamming(64);
hamming_words = uint32(round(hamming_win * (2^8 - 1)));

write_bram_json( ...
    output_dir, ...
    'hamming_default.json', ...
    'Hamming apodization coefficients generated by para_hamming_quant.m', ...
    {'hamming'}, ...
    {hamming_words});
write_C_array_file( ...
    fullfile(output_dir, 'c_array', 'hamming_hex.c'), ...
    'u32 hamming_hex[]', hamming_words, 2, 16,  sprintf('\t'));
end
